import { useEffect, useRef, useState, type CSSProperties } from "react";
import { hasFinePointer, isLowPower, watchVisibility } from "@/lib/performance";

/**
 * Two discs: rotating orange rim (left) + cursor-following eye (right).
 * Standalone Framer code component. All assets are embedded as data URIs.
 *
 * @framerIntrinsicWidth 304
 * @framerIntrinsicHeight 152
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */

const IMG_RIM = "data:image/svg+xml;base64,";
const IMG_RIM_MARKS = "data:image/png;base64,";
const IMG_INNER = "data:image/svg+xml;base64,";
const IMG_EYE_OUTER = "data:image/svg+xml;base64,";
const IMG_EYE_INNER = "data:image/svg+xml;base64,";
const IMG_EYE_SHAPE = "data:image/svg+xml;base64,";
const IMG_EYE_MASK = "data:image/svg+xml;base64,";
const IMG_PUPIL = "data:image/svg+xml;base64,";
const IMG_EYE_OVERLAY = "data:image/png;base64,";
const IMG_EYE_CANVAS = "data:image/png;base64,";

const DESIGN_WIDTH = 303.96;
const DESIGN_HEIGHT = 151.98;
const DISC = 151.98;
const EYE_SIZE = 105.217;

// Elliptical travel range for the pupil (design px), keeping it within the eye shape.
const PUPIL_RX = 14;
const PUPIL_RY = 3.5;
// Cursor distance (design px) at which the pupil reaches full travel.
const FULL_TRAVEL_DISTANCE = 240;
// Fraction of remaining distance covered per 60fps frame: gentle damping, no overshoot.
const DAMPING = 0.09;
const REDUCED_MOTION_FACTOR = 0.2;
// The pupil is settled once it's within this many design px of its target.
const SETTLED = 0.01;

const SPIN_CLASS = "two-discs-rim-spin";
const SPIN_CSS = `
@keyframes two-discs-rim-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
.${SPIN_CLASS} { animation: two-discs-rim-spin 8s linear infinite; transform-origin: 50% 50%; will-change: transform; }
@media (prefers-reduced-motion: reduce) { .${SPIN_CLASS} { animation: none; } }
`;

const abs = (left: number, top: number, width: number, height = width): CSSProperties => ({
  position: "absolute",
  left,
  top,
  width,
  height,
});

const fillImg: CSSProperties = {
  position: "absolute",
  inset: 0,
  display: "block",
  width: "100%",
  height: "100%",
  maxWidth: "none",
  pointerEvents: "none",
  userSelect: "none",
};

function RotatedImage({
  offset,
  box,
  rotate,
  src,
}: {
  offset: number;
  box: number;
  rotate: number;
  src: string;
}) {
  return (
    <div
      style={{
        ...abs(offset, offset, box),
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        pointerEvents: "none",
      }}
    >
      <div style={{ flex: "none", transform: `rotate(${rotate}deg)` }}>
        <div style={{ position: "relative", width: 146.928, height: 146.928 }}>
          <img alt="" draggable={false} src={src} style={{ ...fillImg, objectFit: "cover" }} />
        </div>
      </div>
    </div>
  );
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export default function TwoDiscs(props: { style?: CSSProperties }) {
  const rootRef = useRef<HTMLDivElement>(null);
  const spinRef = useRef<HTMLDivElement>(null);
  const eyeRef = useRef<HTMLDivElement>(null);
  const pupilRef = useRef<HTMLImageElement>(null);
  const [scale, setScale] = useState(1);
  const reducedMotion = usePrefersReducedMotion();

  // Scale the fixed-proportion artwork to fit the frame Framer gives us.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      const s = Math.min(width / DESIGN_WIDTH, height / DESIGN_HEIGHT);
      setScale(Number.isFinite(s) && s > 0 ? s : 1);
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  // The rim spins only while on screen, and rests in low-power mode.
  useEffect(() => {
    const root = rootRef.current;
    const spin = spinRef.current;
    if (!root || !spin) return;
    const lowPower = isLowPower();
    spin.style.animationPlayState = "paused";
    return watchVisibility(root, (visible) => {
      spin.style.animationPlayState = visible && !lowPower ? "running" : "paused";
    });
  }, []);

  // Cursor-following pupil: mouse and trackpad only, and only while on screen. The loop sleeps once the pupil
  // reaches its target and the pointer or a scroll wakes it.
  useEffect(() => {
    const root = rootRef.current;
    const eye = eyeRef.current;
    const pupil = pupilRef.current;
    if (!root || !eye || !pupil || !hasFinePointer()) return;

    let center = { x: 0, y: 0 };
    let unitScale = 1;
    const target = { x: 0, y: 0 };
    const current = { x: 0, y: 0 };
    let pointer: { x: number; y: number } | null = null;
    let frame = 0;
    let visible = false;
    // Layout is read lazily, at most once a frame, instead of on every scroll event.
    let stale = true;
    let last = performance.now();
    const factor = reducedMotion ? REDUCED_MOTION_FACTOR : 1;

    const updateTarget = () => {
      if (!pointer) {
        target.x = 0;
        target.y = 0;
        return;
      }
      const dx = pointer.x - center.x;
      const dy = pointer.y - center.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 0.001) {
        target.x = 0;
        target.y = 0;
        return;
      }
      const ux = dx / dist;
      const uy = dy / dist;
      // Distance from center to the ellipse boundary along this direction.
      const edge = 1 / Math.hypot(ux / PUPIL_RX, uy / PUPIL_RY);
      const reach = Math.min(1, dist / (FULL_TRAVEL_DISTANCE * unitScale)) * edge * factor;
      target.x = ux * reach;
      target.y = uy * reach;
    };

    const measure = () => {
      const r = eye.getBoundingClientRect();
      center = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      unitScale = r.width / EYE_SIZE || 1;
      stale = false;
    };

    const tick = (now: number) => {
      frame = 0;
      if (stale) {
        measure();
        updateTarget();
      }
      const dt = Math.min(64, now - last);
      last = now;
      const k = 1 - Math.pow(1 - DAMPING, dt / 16.667);
      current.x += (target.x - current.x) * k;
      current.y += (target.y - current.y) * k;
      pupil.style.transform = `translate3d(${current.x.toFixed(3)}px, ${current.y.toFixed(3)}px, 0)`;
      const moving = Math.abs(target.x - current.x) > SETTLED || Math.abs(target.y - current.y) > SETTLED;
      if (visible && (moving || stale)) frame = requestAnimationFrame(tick);
    };

    const wake = () => {
      if (frame || !visible) return;
      last = performance.now();
      frame = requestAnimationFrame(tick);
    };

    const invalidate = () => {
      stale = true;
      // A still pupil only needs a new target if there's a pointer to look at.
      if (pointer) wake();
    };

    const onMove = (e: PointerEvent) => {
      pointer = { x: e.clientX, y: e.clientY };
      if (!stale) updateTarget();
      wake();
    };
    const onLeave = (e: MouseEvent) => {
      if (!e.relatedTarget) {
        pointer = null;
        updateTarget();
        wake();
      }
    };
    const onBlur = () => {
      pointer = null;
      updateTarget();
      wake();
    };

    const ro = new ResizeObserver(invalidate);
    ro.observe(eye);
    ro.observe(document.documentElement);
    window.addEventListener("resize", invalidate);
    window.addEventListener("scroll", invalidate, { passive: true, capture: true });
    window.addEventListener("pointermove", onMove, { passive: true });
    document.addEventListener("mouseout", onLeave);
    window.addEventListener("blur", onBlur);
    const unwatch = watchVisibility(root, (next) => {
      visible = next;
      if (visible) {
        stale = true;
        wake();
      } else if (frame) {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    });

    return () => {
      cancelAnimationFrame(frame);
      unwatch();
      ro.disconnect();
      window.removeEventListener("resize", invalidate);
      window.removeEventListener("scroll", invalidate, { capture: true });
      window.removeEventListener("pointermove", onMove);
      document.removeEventListener("mouseout", onLeave);
      window.removeEventListener("blur", onBlur);
    };
  }, [reducedMotion]);

  return (
    <div
      ref={rootRef}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "visible",
        ...props.style,
      }}
    >
      <style>{SPIN_CSS}</style>
      <div
        style={{
          flex: "none",
          width: DESIGN_WIDTH * scale,
          height: DESIGN_HEIGHT * scale,
          position: "relative",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: DESIGN_WIDTH,
            height: DESIGN_HEIGHT,
            display: "flex",
            alignItems: "center",
            transform: `scale(${scale})`,
            transformOrigin: "0 0",
          }}
        >
          {/* Left disc */}
          <div style={{ position: "relative", flex: "none", width: DISC, height: DISC }}>
            {/* Rotating rim: orange ring + rim markings, spun around the disc's exact center */}
            <div ref={spinRef} className={SPIN_CLASS} style={{ position: "absolute", inset: 0 }}>
              <div style={abs(0, 0, DISC)}>
                <img alt="" draggable={false} src={IMG_RIM} style={fillImg} />
              </div>
              <RotatedImage offset={-27.75} box={207.483} rotate={138.1} src={IMG_RIM_MARKS} />
            </div>
            {/* Stationary inner circle */}
            <div style={abs(23.38, 23.38, EYE_SIZE)}>
              <img alt="" draggable={false} src={IMG_INNER} style={fillImg} />
            </div>
          </div>

          {/* Right disc */}
          <div style={{ position: "relative", flex: "none", width: DISC, height: DISC }}>
            <div style={abs(0, 0, DISC)}>
              <img alt="" draggable={false} src={IMG_EYE_OUTER} style={fillImg} />
            </div>
            <div ref={eyeRef} style={{ ...abs(23.38, 23.38, EYE_SIZE), overflow: "hidden" }}>
              <img alt="" draggable={false} src={IMG_EYE_INNER} style={fillImg} />
              <div style={abs(16.32, 30.32, 72.718, 44.004)}>
                <div
                  style={{
                    position: "absolute",
                    top: "13.81%",
                    right: "9.86%",
                    bottom: "13.33%",
                    left: "7.57%",
                  }}
                >
                  <img alt="" draggable={false} src={IMG_EYE_SHAPE} style={fillImg} />
                </div>
                {/* Mask box matches the eye shape's bounds, so the pupil is clipped only by the eye outline */}
                <div
                  style={{
                    ...abs(5.503, 6.075, 60.044, 32.06),
                    maskImage: `url("${IMG_EYE_MASK}")`,
                    WebkitMaskImage: `url("${IMG_EYE_MASK}")`,
                    maskMode: "alpha",
                    maskRepeat: "no-repeat",
                    WebkitMaskRepeat: "no-repeat",
                    maskPosition: "0 0",
                    WebkitMaskPosition: "0 0",
                    maskSize: "100% 100%",
                    WebkitMaskSize: "100% 100%",
                  }}
                >
                  <img
                    ref={pupilRef}
                    alt=""
                    draggable={false}
                    src={IMG_PUPIL}
                    style={{
                      ...abs(17.141, 3.038, 25.763, 25.983),
                      display: "block",
                      maxWidth: "none",
                      pointerEvents: "none",
                      willChange: "transform",
                    }}
                  />
                </div>
              </div>
            </div>
            <RotatedImage offset={-25.76} box={203.489} rotate={56.67} src={IMG_EYE_OVERLAY} />
            <div
              style={{
                ...abs(0, 0, DISC),
                borderRadius: 75.99,
                pointerEvents: "none",
              }}
            >
              <img
                alt=""
                draggable={false}
                src={IMG_EYE_CANVAS}
                style={{ ...fillImg, objectFit: "contain", borderRadius: 75.99 }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
